const std = @import("std");

const FibonacciIterator = struct {
    a: u32 = 0,
    b: u32 = 1,
    remaining: usize,

    fn next(self: *FibonacciIterator) ?u32 {
        if (self.remaining == 0) return null;
        const result = self.a;
        const next = self.a + self.b;
        self.a = self.b;
        self.b = next;
        self.remaining -= 1;
        return result;
    }
};

pub fn main() !void {
    var iter = FibonacciIterator{ .remaining = 10 };
    while (iter.next()) |val| {
        std.debug.print("{} ", .{val});
    }
    std.debug.print("\n", .{});
}
